<?php require_once __DIR__.'/../includes/functions.php';header('Content-Type: application/json');if(empty($_SESSION['admin_id'])){http_response_code(401);echo json_encode(['error'=>'Unauthorized']);exit;}if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['error'=>'POST required']);exit;}verify_csrf();$data=json_decode(file_get_contents('php://input'),true)?:$_POST;try{$s=db()->prepare('INSERT INTO ar_hotspots(poster_id,attraction_id,label,x,y,width,height,z_index,video_url,content_type) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([(int)$data['poster_id'],($data['attraction_id']??null)?(int)$data['attraction_id']:null,trim((string)$data['label']),max(0,min(1,(float)$data['x'])),max(0,min(1,(float)$data['y'])),max(.01,min(1,(float)($data['width']??.2))),max(.01,min(1,(float)($data['height']??.12))),(int)($data['z_index']??1),$data['video_url']??null,$data['content_type']??'card']);echo json_encode(['ok'=>true,'id'=>(int)db()->lastInsertId()]);}catch(Throwable $e){http_response_code(422);echo json_encode(['error'=>'Could not save hotspot']);}
